function catalogGroup(p){return p.details?.catalog_group||({pork:'grill',lamb:'grill',beef:'grill',poultry:'grill',lula:'grill',tandoor:'grill',vegetables:'grill',snacks:'cold',pickles:'cold',cheese:'cold',herbs:'cold',khinkali:'hot',khachapuri:'hot'})[p.category]||p.category}
function inCatalogGroup(p,group){return catalogGroup(p)===group||p.details?.display_categories?.includes(group)}
function canOrder(p){return p&&p.pricing_status!=='pending'&&!p.details?.identity_pending&&p.active!==0&&p.stock>0}
function priceLabel(p){return p.pricing_status==='pending'||p.details?.identity_pending?t('pricePending'):money(p.price)+(p.details?.sale_unit==='kg'?' / '+t('kilogram'):'')}
let allowAlcoholPairings=false;
function storedValue(key){try{return localStorage.getItem(key)}catch{return null}}
function storeValue(key,value){try{localStorage.setItem(key,value);return true}catch{return false}}
let lang=(typeof location!=='undefined'?new URL(location.href).searchParams.get('lang'):null)||storedValue('rai.lang')||'ru';if(!words[lang])lang='ru';storeValue('rai.lang',lang);let adminProducts=[],feastQuote=null,products=[],cart=[],filter='',quote=null,key=crypto.randomUUID();try{cart=JSON.parse(storedValue('rai.cart')||'[]')}catch{};
const t=k=>words[lang][k]||k,money=x=>new Intl.NumberFormat(lang,{style:'currency',currency:'GEL'}).format(x/100),name=p=>p.names[lang]||p.names.ru;
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('on');setTimeout(()=>$('#toast').classList.remove('on'),5000)}
async function api(path,data,admin=false){const h={'Content-Type':'application/json','Idempotency-Key':key};if(admin)h.Authorization='Bearer '+$('#adminToken').value;const r=await fetch('/api/'+path,{method:data?'POST':'GET',headers:h,body:data?JSON.stringify(data):undefined});const j=await r.json();if(!r.ok)throw Error(j.error);return j}
function error(e){if(e.message==='PORTION_UNCONFIRMED'){toast(t('portionPending'));return}if(e.message==='PRICE_UNAPPROVED'){toast(t('pricePending'));return}if(e.message==='CITY_UNAVAILABLE'){toast(t('cityClosed'));return}if(e.message==='INVALID_NAME'){toast(t('invalidCustomerName'));return}toast(['OUT_OF_STOCK','NO_SUITABLE_PRODUCTS','INSUFFICIENT_STOCK'].includes(e.message)?t('noProducts'):t('error'))}
function safeImage(p){if(/^\/media\/[a-f0-9]+\.(jpg|jpeg|png|webp)$/.test(p.details?.image||''))return p.details.image;try{const u=new URL(p.details?.image);return u.protocol==='https:'?u.href:''}catch{return ''}}
function photo(p){const src=safeImage(p);return `<div class="photo-frame">${src?`<img src="${esc(src)}" alt="${esc(name(p))}" loading="lazy" referrerpolicy="no-referrer">`:`<div class="placeholder">${t('noPhoto')}</div>`}</div>`}
function getMotionContext(){return {products,lang,openProduct,cartCount:cart.reduce((n,l)=>n+l.quantity,0)}}
function render(){document.documentElement.lang=lang;document.title=brand[lang];$('#appManifest').href='/manifest-'+lang+'.webmanifest';$('#appleAppTitle').content=brand[lang];document.querySelectorAll('[data-brand]').forEach(e=>e.textContent=brand[lang]);$('#language').value=lang;document.querySelectorAll('[data-t]').forEach(e=>e.textContent=t(e.dataset.t));$('#search').placeholder=t('search');$('#categories').innerHTML=['',...SHOP_GROUP_ORDER.filter(c=>products.some(p=>inCatalogGroup(p,c)))].map(c=>`<button class="${c===filter?'selected':''}" data-cat="${c}" aria-pressed="${c===filter}">${c?shopGroupNames[lang][c]:t('all')}</button>`).join('');$('#adminCategory').innerHTML=cats.map((c,i)=>`<option value="${c}">${catNames[lang][i]}</option>`).join('');const meatState=$('#meatChoices').innerHTML?[...document.querySelectorAll('#meatChoices input')].filter(e=>e.checked).map(e=>e.value):null;$('#meatChoices').innerHTML=['pork','lamb','beef','poultry','fish','tandoor','lula'].map(c=>`<label><input type="checkbox" name="meat" value="${c}" ${meatState===null||meatState.includes(c)?'checked':''}>${catNames[lang][cats.indexOf(c)]}</label>`).join('');const list=products.filter(p=>(!filter||inCatalogGroup(p,filter))&&name(p).toLowerCase().includes($('#search').value.toLowerCase())).sort((a,b)=>SHOP_GROUP_ORDER.indexOf(catalogGroup(a))-SHOP_GROUP_ORDER.indexOf(catalogGroup(b)));$('#products').innerHTML=list.length?list.map(p=>`<article class="card" data-product-id="${esc(p.id)}"><button class="product-photo-link" data-detail="${esc(p.id)}" aria-label="${esc(name(p))}">${photo(p)}</button><p class="tag">${shopGroupNames[lang][catalogGroup(p)]||catNames[lang][cats.indexOf(p.category)]}</p><h3><button data-detail="${esc(p.id)}">${esc(name(p))}</button></h3><p>${p.details?.sale_unit==='kg'?t('perKilogram'):p.details?.volume_ml?p.details.volume_ml+' ml':p.details?.weight_unknown?t('portion'):p.grams+' g'}</p>${bundleInfo(p)}<footer><strong>${priceLabel(p)}</strong><button data-add="${esc(p.id)}" ${canOrder(p)?'':'disabled'}>${t('add')}</button></footer>${lastAddedId===p.id?'<div id="catalogSuggestions"></div>':''}</article>`).join(''):`<div class="empty-menu"><div class="eyebrow">${t('catalog')}</div><h3>${t('empty')}</h3><p>${t('emptyHint')}</p></div>`;$('#bag').textContent=t('cart')+' · '+cart.reduce((a,l)=>a+l.quantity,0);renderSettings();renderAlcoholAvailability();renderBasketBar();renderContactProfileStatus();syncCatalogNavigation();if(typeof window!=='undefined')window.RaiMotion?.refresh(getMotionContext())}
async function load(){shopSettings=await api('settings');if(shopSettings.demo)for(const l of Object.keys(demoWords))Object.assign(words[l],demoWords[l]);products=(await api('catalog')).products;const merged=new Map();for(const line of cart){const p=products.find(p=>p.id===line.id||p.details?.aliases?.includes(line.id));if(p)merged.set(p.id,(merged.get(p.id)||0)+line.quantity)}cart=[...merged].map(([id,quantity])=>({id,quantity}));storeValue('rai.cart',JSON.stringify(cart));render();renderSettings()}
function save(){quote=null;storeValue('rai.cart',JSON.stringify(cart));key=crypto.randomUUID();render()}
let lastAddedId=null;
let drawVersion=0;async function draw(){const version=++drawVersion;quote=null;$('#checkout').hidden=!cart.length;$('#clearCart').disabled=!cart.length;$('#cartLines').innerHTML=cart.length?cart.map(l=>{const p=products.find(p=>p.id===l.id);return `<div class="cartline">${esc(p?name(p):l.id)} · ${l.quantity} <div class="quantity"><button data-change="${esc(l.id)}" data-step="-1" aria-label="−">−</button><button data-change="${esc(l.id)}" data-step="1" aria-label="+">+</button></div><button data-remove="${esc(l.id)}">${t('remove')}</button></div>`}).join(''):`<p>${t('cartEmpty')}</p>`;$('#sum').textContent='';syncOrderChannels();if(cart.length)try{const received=await api('quote',{items:cart});if(version!==drawVersion)return;quote=received;$('#sum').textContent=t('subtotal')+': '+money(quote.total)}catch(e){if(version!==drawVersion)return;$('#checkout').hidden=true;error(e)}syncOrderChannels();recommend()}
$('#language').onchange=e=>{lang=e.target.value;storeValue('rai.lang',lang);render();if(feastQuote)renderFeast();if($('#drawer').open)draw()};$('#search').oninput=()=>{if(typeof window!=='undefined'&&window.RaiMotion)window.RaiMotion.catalogChange(render);else render()};
$('#categories').onclick=e=>{if(e.target.dataset.cat!==undefined){const selected=e.target.dataset.cat;if(selected===filter)return;const update=()=>{filter=selected;render();syncCatalogNavigation();$('#products').scrollIntoView?.({block:'start',behavior:'instant'})};if(typeof window!=='undefined'&&window.RaiMotion)window.RaiMotion.catalogChange(update);else update()}};
$('#products').onclick=e=>{const detail=e.target.closest?.('[data-detail]')?.dataset.detail||e.target.dataset.detail;if(detail){openProduct(detail);return}const id=e.target.dataset.add;if(id){if(!canOrder(products.find(p=>p.id===id)))return;const l=cart.find(l=>l.id===id);l?l.quantity++:cart.push({id,quantity:1});lastAddedId=id;save();toast(t('addedToCart'));showSuggestions('#catalogSuggestions',cart.map(l=>l.id))}};
$('#bag').onclick=()=>{$('#drawer').showModal();draw()};$('#close').onclick=()=>$('#drawer').close();$('#cartLines').onclick=e=>{if(e.target.dataset.change){const l=cart.find(l=>l.id===e.target.dataset.change);if(l){l.quantity+=+e.target.dataset.step;cart=cart.filter(l=>l.quantity>0);save();draw()}return}if(e.target.dataset.remove){cart=cart.filter(l=>l.id!==e.target.dataset.remove);save();draw()}};
let feastRequest=null,feastBusy=false,feastVersion=0,feastValid=true;
function feastWarning(code){if(code.startsWith('missing_')){const key=code.slice(8);return t('missingTableItem')+': '+({vodka:t('alcoholVodka'),wine:t('alcoholWine'),beer:t('alcoholBeer'),chacha:t('alcoholChacha'),cognac:t('alcoholCognac'),salads:t('feastSalads'),bread:t('feastBread'),sauces:t('feastSauces'),vegetables:t('feastVegetables'),starters:t('feastStarters'),water:t('feastWater'),softDrinks:t('feastSoftDrinks')})[key]}if(code==='water_volume_unknown')return t('waterVolumeUnknown');if(code.startsWith('budget_excluded_'))return t('optionalExcluded');return ''}
function feastAlternatives(group,line){return products.filter(p=>canOrder(p)&&(group==='hot'?['pork','lamb','beef','poultry','fish','tandoor','lula'].includes(p.category)&&!p.details?.weight_unknown:group==='salads'?p.category==='salads':group==='bread'?p.category==='bread':group==='sauces'?p.category==='sauces':group==='vegetables'?p.category==='vegetables':group==='water'?p.category==='drinks'&&/вода/i.test(p.names.ru):group==='alcohol'?p.category==='alcohol'&&(!line?.alcohol_type||p.details?.alcohol_type===line.alcohol_type):group==='softDrinks'?p.category==='drinks'&&!/вода/i.test(p.names.ru):group==='starters'?['snacks','cheese','pickles','herbs'].includes(p.category):false))}
function renderFeast(){if(!feastQuote)return;const q=feastQuote;const budget=feastRequest?.budget;const over=budget!==undefined&&q.total>budget;const hot=q.lines.filter(l=>l.group==='hot').reduce((sum,l)=>sum+(l.grams||0)*l.quantity,0);const low=hot<(q.required_grams||0);$('#feastResult').innerHTML=`<div class="feast-summary"><div><span>${t('selectedTable')}</span><h3>${q.guests} · ${t('guestsLabel')}</h3></div><div><strong>${money(q.total)}</strong><p>${budget===undefined?'':over?t('budgetOver')+' '+money(q.total-budget):t('budgetLeft')+' '+money(budget-q.total)}</p></div></div>${feastAlcoholSummary(q)}<p>${t('hotWeight')}: ${(hot/1000).toFixed(2)} kg · ${t('foodWeight')}: ${(q.grams/1000).toFixed(2)} kg</p>${low?`<p class="feast-alert">${t('notEnoughHot')}</p>`:''}${over?`<p class="feast-alert">${t('budgetOverNotice')}</p>`:''}<div class="feast-lines">${q.lines.map(l=>{const p=products.find(p=>p.id===l.id);const alternatives=feastAlternatives(l.group,l);return `<article class="feast-item">${p?photo(p):''}<div class="feast-item-content"><span class="tag">${t('group_'+l.group)}</span><h4>${esc(l.names[lang]||l.names.ru)}</h4><p>${l.volume_ml?l.volume_ml+' ml':l.grams?l.grams+' g':t('portion')} · ${money(l.price)} × ${l.quantity} = <strong>${money(l.price*l.quantity)}</strong></p><div class="quantity"><button type="button" data-feast-quantity="${l.id}" data-step="-1" aria-label="−">−</button><span>${l.quantity}</span><button type="button" data-feast-quantity="${l.id}" data-step="1" aria-label="+">+</button><button type="button" data-feast-remove="${l.id}">${t('remove')}</button></div><details><summary>${t('replaceDish')}</summary><label>${t('replacementChoice')}<select data-feast-replace="${l.id}">${alternatives.map(x=>`<option value="${x.id}" ${l.id===x.id?'selected':''}>${esc(name(x))} · ${money(x.price)}</option>`).join('')}</select></label></details></div></article>`}).join('')}</div>${(q.optional||[]).length?`<details><summary>${t('optionalExcluded')}</summary>${q.optional.map(l=>`<p>${esc(l.names[lang]||l.names.ru)} × ${l.quantity} · ${money(l.price*l.quantity)}</p>`).join('')}</details>`:''}${(q.warnings||[]).map(w=>feastWarning(w)).filter(Boolean).map(w=>`<p class="feast-alert">${esc(w)}</p>`).join('')}<details class="feast-method"><summary>${t('methodTitle')}</summary><p>${t('methodExplanation')}</p></details><div class="feast-actions"><button type="button" class="primary" id="acceptFeast" ${feastBusy||!feastValid||!q.items.length?'disabled':''}>${t('addFeast')} · ${money(q.total)}</button><button type="button" id="rebuildFeast">${t('rebuildFeast')}</button></div>`;$('#acceptFeast').onclick=()=>{if(feastBusy||!feastValid||!feastQuote.items.length)return;for(const l of feastQuote.items){const old=cart.find(x=>x.id===l.id);old?old.quantity+=l.quantity:cart.push({...l})}save();toast(t('addedToCart'))};$('#rebuildFeast').onclick=()=>$('#feastForm').requestSubmit();if(typeof window!=='undefined')window.RaiMotion?.observe()}
async function recalculateFeast(){const version=++feastVersion;feastBusy=true;const add=$('#acceptFeast');if(add)add.disabled=true;try{const items=feastQuote.lines.map(l=>({id:l.id,quantity:l.quantity}));if(!items.length){feastQuote.items=[];feastQuote.total=0;feastQuote.grams=0;return}const q=await api('quote',{items});if(version!==feastVersion)return;feastValid=true;feastQuote.items=items;feastQuote.total=q.total;feastQuote.grams=feastQuote.lines.filter(l=>!['water','softDrinks','alcohol'].includes(l.group)).reduce((sum,l)=>sum+(l.grams||0)*l.quantity,0);for(const row of feastQuote.lines){const quoted=q.lines.find(l=>l.id===row.id);if(quoted)row.price=quoted.price}}catch(e){if(version===feastVersion){feastValid=false;error(e)}}finally{if(version===feastVersion){feastBusy=false;renderFeast()}}}
$('#feastResult').onclick=e=>{const remove=e.target.dataset.feastRemove,quantity=e.target.dataset.feastQuantity;if(remove){feastQuote.lines=feastQuote.lines.filter(l=>l.id!==remove);recalculateFeast()}if(quantity){const line=feastQuote.lines.find(l=>l.id===quantity);if(!line)return;line.quantity=Math.max(1,Math.min(100,line.quantity+Number(e.target.dataset.step)));recalculateFeast()}};
$('#feastResult').onchange=e=>{const id=e.target.dataset.feastReplace;if(!id)return;const line=feastQuote.lines.find(l=>l.id===id),p=products.find(p=>p.id===e.target.value);if(!line||!p)return;const other=feastQuote.lines.find(l=>l.id===p.id&&l.id!==id);if(other){other.quantity+=line.quantity;feastQuote.lines=feastQuote.lines.filter(l=>l.id!==id)}else Object.assign(line,{id:p.id,names:p.names,price:p.price,grams:p.details?.weight_unknown?null:p.grams,image:p.details?.image,volume_ml:p.details?.volume_ml||null,...(line.group==='alcohol'?{alcohol_type:p.details?.alcohol_type}:{} )});recalculateFeast()};
$('#feastForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target),p=Object.fromEntries(fd);feastRequest={adults:+p.adults,children:+p.children,categories:fd.getAll('meat'),...(p.budget?{budget:Math.round(+p.budget*100)}:{}),budgetMode:'target',alcoholSelections:fd.getAll('alcoholType').map(type=>({type,quantity:+p['alcoholQty_'+type],...(p['alcoholProduct_'+type]?{productId:p['alcoholProduct_'+type]}:{})}))};for(const key of ['salads','bread','sauces','vegetables','starters','water','softDrinks'])feastRequest[key]=fd.has(key);const version=++feastVersion;feastBusy=true;$('#feastResult').innerHTML='<p>'+t('calculatingTable')+'</p>';try{const q=await api('feast',feastRequest);if(version!==feastVersion)return;feastQuote=q;feastValid=true;feastBusy=false;renderFeast();$('#feastResult').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'})}catch(e){if(version!==feastVersion)return;$('#feastResult').textContent=t(e.message==='NO_SUITABLE_PRODUCTS'?'noProducts':'error');error(e)}finally{if(version===feastVersion)feastBusy=false}};
$('#checkout').onsubmit=async e=>{e.preventDefault();rememberCheckoutProfile();if(!quote)return;const button=e.target.querySelector('[type="submit"]');button.disabled=true;try{const o=await api('orders',{...Object.fromEntries(new FormData(e.target)),items:cart,confirmed_total:quote.total});if(!o.demo)storeValue('rai.lastOrder',JSON.stringify({...o,items:cart}));$('#orderResult').textContent=(o.demo?t('demoOrder'):t('order'))+': '+o.id;cart=[];save();await draw()}catch(e){error(e)}finally{button.disabled=false}};
