const suggestionVersions=new Map();
async function showSuggestions(selector,selected){const element=$(selector);if(!element)return;const version=(suggestionVersions.get(selector)||0)+1;suggestionVersions.set(selector,version);try{const result=await api('recommendations',{selected:[...new Set(selected)],allowAlcohol:allowAlcoholPairings});if(suggestionVersions.get(selector)!==version)return;const offers=result.recommendations.map(x=>({product:products.find(p=>p.id===x.id),reason:x.reason})).filter(x=>x.product);element.innerHTML=offers.length?`<h3>${t('recommendTitle')}</h3><div class="suggestion-grid">${offers.map(({product:p,reason})=>`<article class="suggestion-item">${photo(p)}<div><strong>${esc(name(p))}</strong><p>${t(reason)}</p><span>${priceLabel(p)}</span><button type="button" data-recommend="${p.id}">${t('add')}</button></div></article>`).join('')}</div>`:''}catch{element.innerHTML=''}}
