const FEAST_ALCOHOL_TYPES=['wine','vodka','cognac','beer','chacha'];
function renderAlcoholAvailability(){const missing=[];for(const type of FEAST_ALCOHOL_TYPES){const enabled=$('#alcohol-'+type).checked,select=$('#alcoholProduct-'+type),chosen=select.value;const options=products.filter(p=>p.category==='alcohol'&&canOrder(p)&&p.details?.alcohol_type===type);select.innerHTML=`<option value="">${t('autoAlcohol')}</option>`+options.map(p=>`<option value="${p.id}">${esc(name(p))} · ${p.details.volume_ml||''} ml · ${priceLabel(p)}</option>`).join('');select.value=options.some(p=>p.id===chosen)?chosen:'';select.disabled=!enabled;$('#alcoholQty-'+type).disabled=!enabled;if(enabled&&!options.length)missing.push(t({wine:'alcoholWine',vodka:'alcoholVodka',cognac:'alcoholCognac',beer:'alcoholBeer',chacha:'alcoholChacha'}[type]))}$('#alcoholAvailability').textContent=missing.length?t('alcoholUnavailable')+' '+missing.join(', '):''}
function feastAlcoholSummary(q){const rows=q.lines.filter(l=>l.group==='alcohol');if(rows.length)return `<p class="feast-alert">${t('alcoholIncluded')}: ${rows.map(l=>`${esc(l.names[lang]||l.names.ru)} × ${l.quantity} — ${money(l.price*l.quantity)}`).join('; ')}</p>`;return (feastRequest?.alcoholSelections?.length||(feastRequest?.alcohol&&feastRequest.alcohol!=='none'))?`<p class="feast-alert" role="status">${t('alcoholNotIncluded')}</p>`:''}
$('#feastAlcohol').onchange=renderAlcoholAvailability;


