function bundleInfo(p,full=false){const b=p.details?.bundle;if(!b)return '';const g=b.servings;const count=g?.min?(g.min===g.max?String(g.min):g.min+'–'+g.max):'';const guests=count?t('setGuests').replace('{n}',count):t('setGuestsUnknown');const basis=g?.basis==='source'?t('setGuestsSource'):g?.basis==='estimate'?t('setGuestsEstimate'):'';const contents=`<ul>${b.components.map(x=>{const amount=x.grams_per_piece&&x.quantity?`${x.quantity} ${t('setPcs')} × ${x.grams_per_piece} ${t('setGrams')} = ${x.grams} ${t('setGrams')}`:[x.quantity?x.quantity+' '+t('setPcs'):'',x.grams?x.grams+' '+t('setGrams'):''].filter(Boolean).join(' · ');return `<li><span>${esc(x.names[lang]||x.names.ru)}</span><strong>${esc(amount||t('setQuantityUnknown'))}</strong></li>`}).join('')}</ul>${b.components.some(x=>!x.quantity&&!x.grams)?`<p class="set-note">${t('setMissingAmounts')}</p>`:''}${(b.notes||[]).map(n=>`<p class="set-note">${esc(t('set_'+n))}</p>`).join('')}`;return `<div class="set-info"><p class="set-guests">${esc(guests)}</p>${basis?`<p class="set-note">${esc(basis)}</p>`:''}${full?`<h3>${t('setComposition')}</h3>${contents}`:`<details><summary>${t('setComposition')} · ${b.components.length} ${t('setParts')}</summary>${contents}</details>`}</div>`}


