function currentDeliveryCity(){const cities=shopSettings.cities;if(!Array.isArray(cities))return {id:'akhalkalaki',names:shopSettings.city||{},active:true};return cities.find(c=>c.id===selectedCityId&&c.active===true)||cities.find(c=>c.id===shopSettings.default_city_id&&c.active===true)||cities.find(c=>c.active===true)||null}
function renderCities(){const current=currentDeliveryCity(),term=$('#citySearch').value.trim().toLocaleLowerCase(lang);if(current)selectedCityId=current.id;$('#orderCity').value=current?.id||'';$('#orderCityName').value=current?.names[lang]||shopSettings.city?.[lang]||'';const list=(shopSettings.cities||[]).filter(c=>Object.values(c.names).some(name=>name.toLocaleLowerCase(lang).includes(term)));$('#cityList').innerHTML=list.length?list.map(c=>`<button type="button" class="city-option ${c.active?'city-active':''}" data-city="${c.id}" ${c.active!==true?'disabled':''} ${c.id===current?.id?'aria-current="true"':''}><span>${esc(c.names[lang]||c.names.ru)}</span><small>${t(c.active===true?'cityAvailable':'citySoon')}</small></button>`).join(''):`<p>${t('cityNotFound')}</p>`}
function openCities(){$('#citySearch').value='';renderCities();$('#cityDialog').showModal();$('#citySearch').focus?.()}
$('#cityClose').onclick=()=>$('#cityDialog').close();$('#citySearch').oninput=renderCities;$('#cityList').onclick=e=>{const id=e.target.closest?.('[data-city]')?.dataset.city||e.target.dataset.city;const city=(shopSettings.cities||[]).find(c=>c.id===id&&c.active===true);if(!city)return;selectedCityId=city.id;renderSettings();$('#cityDialog').close()};


