const CONTACT_KEY='rai.checkout.v1';let contactStorageOK=true,hasSavedContacts=false;
const contactFields={customer_name:['#customerName',100],phone:['#customerPhone',30],address:['#customerAddress',500]};
function readCheckoutProfile(){let raw;try{raw=localStorage.getItem(CONTACT_KEY)}catch{contactStorageOK=false;return {}}try{const data=JSON.parse(raw||'null');return data&&data.version===1&&typeof data==='object'?data:{}}catch{return {}}}
function renderContactProfileStatus(){const note=$('#profileStatus');if(note)note.textContent=t(contactStorageOK?'rememberContactHint':'contactStorageUnavailable');const button=$('#forgetContact');if(button)button.disabled=!hasSavedContacts&&!Object.values(contactFields).some(([id])=>$(id)?.value)}
function rememberCheckoutProfile(){const old=readCheckoutProfile(),values={};for(const [key,[id,max]]of Object.entries(contactFields))values[key]=($(id)?.value||'').slice(0,max).trim();const city=$('#orderCity').value||currentDeliveryCity()?.id||'akhalkalaki';const addresses={};if(old.addresses&&typeof old.addresses==='object')for(const [id,value]of Object.entries(old.addresses))if(/^[a-z0-9-]{1,60}$/.test(id)&&typeof value==='string'&&value.length<=500)addresses[id]=value;if(values.address)addresses[city]=values.address;else delete addresses[city];hasSavedContacts=!!(values.customer_name||values.phone||Object.keys(addresses).length);try{if(hasSavedContacts)localStorage.setItem(CONTACT_KEY,JSON.stringify({version:1,customer_name:values.customer_name,phone:values.phone,addresses}));else localStorage.removeItem(CONTACT_KEY);contactStorageOK=true}catch{contactStorageOK=false}renderContactProfileStatus()}
function restoreCheckoutProfile(){const data=readCheckoutProfile(),city=$('#orderCity').value||currentDeliveryCity()?.id||'akhalkalaki';const values={customer_name:data.customer_name,phone:data.phone,address:data.addresses?.[city]};for(const [key,[id,max]]of Object.entries(contactFields)){const input=$(id),value=values[key];if(input&&!input.value&&typeof value==='string')input.value=value.slice(0,max)}hasSavedContacts=!!(data.customer_name||data.phone||(data.addresses&&Object.keys(data.addresses).length));renderContactProfileStatus()}
$('#checkout').addEventListener?.('input',rememberCheckoutProfile);$('#checkout').addEventListener?.('change',rememberCheckoutProfile);$('#checkout').addEventListener?.('focusout',rememberCheckoutProfile);
$('#forgetContact').onclick=()=>{for(const [id]of Object.values(contactFields))$(id).value='';hasSavedContacts=false;try{localStorage.removeItem(CONTACT_KEY);contactStorageOK=true}catch{contactStorageOK=false}renderContactProfileStatus();toast(t('contactsForgotten'))};
if(typeof window!=='undefined'&&window.addEventListener){window.addEventListener('pagehide',rememberCheckoutProfile);window.addEventListener('pageshow',restoreCheckoutProfile)}
restoreCheckoutProfile();

