// Real licensed grill footage; no animation loop or canvas effect.
(()=>{if(typeof document.addEventListener!=='function')return;const video=document.getElementById('siteFireVideo');if(!video)return;const motion=matchMedia('(prefers-reduced-motion: reduce)');let loaded=false;
function syncFire(){const still=motion.matches||navigator.connection?.saveData;if(still||document.hidden){video.pause();return}if(!loaded){video.src=matchMedia('(max-width: 767px)').matches?video.dataset.mobile:video.dataset.desktop;video.muted=true;loaded=true}video.play().catch(()=>{})}
video.addEventListener('error',()=>{video.hidden=true});document.addEventListener('visibilitychange',syncFire);motion.addEventListener('change',syncFire);window.addEventListener('pagehide',()=>video.pause());window.addEventListener('pageshow',syncFire);navigator.connection?.addEventListener?.('change',syncFire);if('requestIdleCallback' in window)window.requestIdleCallback(syncFire,{timeout:1500});else setTimeout(syncFire,250)})();

// Stop document rubber-banding sideways; preserve vertical scroll and local gestures.
(()=>{if(typeof document.addEventListener!=='function')return;let start=null;
const localGesture='input,textarea,select,[contenteditable],#categories,.showcase-media';
document.addEventListener('touchstart',e=>{start=e.touches.length===1&&!e.target.closest?.(localGesture)?{id:e.touches[0].identifier,x:e.touches[0].clientX,y:e.touches[0].clientY,axis:null}:null},{passive:true});
document.addEventListener('touchmove',e=>{if(!start||e.touches.length!==1||e.touches[0].identifier!==start.id){start=null;return}const dx=Math.abs(e.touches[0].clientX-start.x),dy=Math.abs(e.touches[0].clientY-start.y);if(!start.axis&&Math.max(dx,dy)>10)start.axis=dx>dy?'x':'y';if(start.axis==='x'&&e.cancelable)e.preventDefault()},{passive:false});
for(const event of ['touchend','touchcancel'])document.addEventListener(event,()=>{start=null},{passive:true});})();

// Sticky category navigation follows the actual responsive header height.
function syncCatalogNavigation(){const header=$('body>header'),categories=$('#categories'),style=document.documentElement?.style;if(!header?.getBoundingClientRect||!categories?.getBoundingClientRect||!style?.setProperty)return;style.setProperty('--header-height',Math.ceil(header.getBoundingClientRect().height)+'px');style.setProperty('--categories-height',Math.ceil(categories.getBoundingClientRect().height)+'px');categories.setAttribute('aria-label',t('catalog'))}
(()=>{if(typeof window==='undefined')return;const header=$('body>header'),categories=$('#categories');if(typeof ResizeObserver!=='undefined'&&header&&categories){const observer=new ResizeObserver(syncCatalogNavigation);observer.observe(header);observer.observe(categories)}window.addEventListener?.('resize',syncCatalogNavigation,{passive:true});syncCatalogNavigation()})();

function storePhone(){const phone=shopSettings.phone||'+995591244075';return /^\+?[1-9]\d{7,14}$/.test(phone)?phone:'+995591244075'}
function whatsappOrderText(includeContacts=false){const parts=[t('whatsappGreeting')];if(quote&&cart.length){parts.push('',...quote.lines.map(l=>(l.names[lang]||l.names.ru)+' × '+l.quantity+' — '+money(l.price*l.quantity)),t('whatsappTotal')+': '+money(quote.total))}if(includeContacts){const city=currentDeliveryCity();if(city)parts.push(t('deliveryCity')+': '+(city.names[lang]||city.names.ru));for(const [selector,key]of [['#customerName','customerName'],['#customerPhone','phone'],['#customerAddress','address']]){const value=$(selector).value.trim();if(value)parts.push(t(key)+': '+value)}}parts.push('',t('whatsappConfirm'));return parts.join('\n')}
function syncOrderChannels(includeContacts=false){const phone=storePhone(),display=shopSettings.phone_display||'+995 591 244 075',base='https://wa.me/'+phone.replace(/\D/g,'');document.querySelectorAll('[data-shop-phone]').forEach(a=>a.href='tel:'+phone);document.querySelectorAll('[data-shop-phone-number]').forEach(e=>e.textContent=display);const contact=$('#whatsappContact'),order=$('#whatsappOrder');if(contact)contact.href=base+'?text='+encodeURIComponent(t('whatsappGreeting'));if(order){order.hidden=!cart.length;order.setAttribute?.('aria-disabled',String(!quote));order.href=quote&&cart.length?base+'?text='+encodeURIComponent(whatsappOrderText(includeContacts)):'#'}const hint=$('#whatsappHint');if(hint)hint.hidden=!cart.length}
$('#whatsappOrder').onclick=e=>{if(!quote||!cart.length){e.preventDefault();return}rememberCheckoutProfile();syncOrderChannels(true)};
